{"sql": "WITH batting_clean AS (
  SELECT TRY_CAST(g AS DOUBLE) as g, TRY_CAST(r AS DOUBLE) as r, TRY_CAST(h AS DOUBLE) as h, TRY_CAST(hr AS DOUBLE) as hr
